#!/usr/bin/env python3
"""生成 scenes/khronos/gallery.js 里的 MODELS 数组（Khronos 画廊的入口索引）。

画廊入口 ``scenes/khronos/index.scn`` 通过 ``overlay_script`` 常驻加载 ``gallery.js``；
脚本用 ``MODELS`` 做「标题 ↔ 场景路径」映射（demo 切换路径 = ``<base>/<Model>/<Model>.scn``）。
本工具扫描 ``scenes/khronos/<Model>/<Model>.scn``，按目录名排序后写入 gallery.js 的
两行标记之间：

    /* MODELS:BEGIN (generated by tools/gen_khronos_gallery.py) */
    const MODELS = [ ... ];
    /* MODELS:END */

设计约束
--------
* **幂等**：同一输入重复运行不产生任何字节变化（内容未变时**不写文件**，mtime 也不动）；
* **确定**：目录名按码点排序（与 JS ``Array.prototype.sort`` 对 ASCII 一致），
  固定缩进/换行（LF）/每行 4 项，不依赖 locale；
* **明确失败**：目录缺失、没有模型、标记缺失/重复、``<Model>/<Model>.scn`` 命名不符
  → 打印中文错误并以非零码退出（不做"看起来成功"的静默降级）。

用法
----
    python tools/gen_khronos_gallery.py            # 就地更新 gallery.js
    python tools/gen_khronos_gallery.py --check    # 只校验：过期 → 退出码 1，不写文件
    python tools/gen_khronos_gallery.py --root .   # 指定仓库根（默认 = 本脚本上一级）
"""

from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

BEGIN_MARK = "/* MODELS:BEGIN (generated by tools/gen_khronos_gallery.py) */"
END_MARK = "/* MODELS:END */"
PER_LINE = 4            # 每行模型数（固定 → 幂等）
INDENT = "  "           # JS 数组元素缩进
NEWLINE = "\n"          # 固定 LF（不随平台变化）


def fail(msg: str) -> "NoReturn":  # noqa: F821 - 仅作类型注解可读性（py3.8 兼容用字符串）
    print(f"gen_khronos_gallery: 错误：{msg}", file=sys.stderr)
    raise SystemExit(2)


def find_models(khronos_dir: Path) -> list[str]:
    """扫描 ``<Model>/<Model>.scn``，返回按目录名排序（码点序）的模型名列表。"""
    if not khronos_dir.is_dir():
        fail(f"目录不存在：{khronos_dir}")
    models: list[str] = []
    for entry in sorted(khronos_dir.iterdir(), key=lambda p: p.name):
        if not entry.is_dir() or entry.name.startswith("."):
            continue
        # 场景路径约定 = <Model>/<Model>.scn（画廊按此拼 director_load_scene 的路径）
        if (entry / f"{entry.name}.scn").is_file():
            models.append(entry.name)
            continue
        strays = sorted(p.name for p in entry.glob("*.scn"))
        if strays:
            fail(
                f"{entry} 下的场景文件名与目录名不一致：{strays}"
                "（画廊约定 <Model>/<Model>.scn）"
            )
    if not models:
        fail(f"{khronos_dir} 下没有找到任何 <Model>/<Model>.scn")
    return models


def render_block(models: list[str]) -> str:
    """MODELS 区块的完整文本（含首尾标记行；固定格式 → 幂等）。"""
    lines = [BEGIN_MARK, "const MODELS = ["]
    for i in range(0, len(models), PER_LINE):
        chunk = models[i : i + PER_LINE]
        # json.dumps 负责加引号/转义（当前模型名全 ASCII，但别假设）
        lines.append(INDENT + " ".join(json.dumps(m, ensure_ascii=False) + "," for m in chunk))
    lines.append("];")
    lines.append(END_MARK)
    return NEWLINE.join(lines)


def replace_block(text: str, block: str, js_path: Path) -> str:
    """把 text 里 BEGIN..END 之间的内容替换为 block（保留区块外的所有字节）。"""
    begin = text.find(BEGIN_MARK)
    if begin < 0:
        fail(f"{js_path} 里找不到起始标记：{BEGIN_MARK}")
    if text.find(BEGIN_MARK, begin + len(BEGIN_MARK)) >= 0:
        fail(f"{js_path} 里有重复的起始标记（应恰好一处）")
    end = text.find(END_MARK, begin)
    if end < 0:
        fail(f"{js_path} 里找不到结束标记：{END_MARK}")
    end_end = end + len(END_MARK)
    return text[:begin] + block + text[end_end:]


def main(argv: list[str]) -> int:
    ap = argparse.ArgumentParser(
        description="生成 scenes/khronos/gallery.js 的 MODELS 数组（幂等）"
    )
    ap.add_argument("--root", type=Path, default=None, help="仓库根目录（默认：本脚本的上一级）")
    ap.add_argument("--gallery", type=Path, default=None, help="gallery.js 路径（默认：<root>/scenes/khronos/gallery.js）")
    ap.add_argument("--check", action="store_true", help="只校验 MODELS 是否最新（不写文件；过期退出码 1）")
    args = ap.parse_args(argv)

    root = args.root.resolve() if args.root else Path(__file__).resolve().parent.parent
    khronos_dir = root / "scenes" / "khronos"
    js_path = args.gallery.resolve() if args.gallery else khronos_dir / "gallery.js"

    models = find_models(khronos_dir)
    if not js_path.is_file():
        fail(f"gallery.js 不存在：{js_path}（先创建带 MODELS 标记的脚本文件）")

    # read_text 已做换行归一化（\r\n → \n）；写回统一 LF，保证跨平台幂等。
    text = js_path.read_text(encoding="utf-8")
    new_text = replace_block(text, render_block(models), js_path)

    changed = new_text != text
    if args.check:
        if changed:
            print(
                f"gen_khronos_gallery: {js_path} 的 MODELS 已过期"
                f"（应为 {len(models)} 项）—— 运行 python tools/gen_khronos_gallery.py",
                file=sys.stderr,
            )
            return 1
        print(f"gen_khronos_gallery: 已是最新（{len(models)} 项）")
        return 0

    if not changed:
        print(f"gen_khronos_gallery: 无变化（{len(models)} 项）→ {js_path}")
        return 0

    js_path.write_text(new_text, encoding="utf-8", newline=NEWLINE)
    print(f"gen_khronos_gallery: 已更新 {js_path}（{len(models)} 项）")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
